          {/* Brand */}
          <div className="lg:col-span-1">
            <img
              src="/airo-assets/images/logo/horizontal?variant=solid"
              alt="Artisan Goods Co."
              className="h-9 w-auto object-contain shrink-0 self-center mb-4 brightness-0 invert"
            />
            <p className="text-sm leading-relaxed" style={{ color: '#A8C5BC' }}>
              Handcrafted goods made with intention. We connect skilled artisans with people who
              appreciate the beauty of things made by hand.
            </p>
            <div className="flex gap-4 mt-5">
              {[
                { Icon: Instagram, label: 'Instagram' },
                { Icon: Facebook, label: 'Facebook' },
                { Icon: Twitter, label: 'Twitter' },
              ].map(({ Icon, label }) => (
