                  key={label}
                  href="#"
                  aria-label={label}
                  className="w-9 h-9 rounded-full flex items-center justify-center transition-colors duration-200 hover:bg-primary"
                  style={{ backgroundColor: '#2D4A3E' }}
                >
                  <Icon size={16} />
                </a>
              ))}
            </div>
          </div>

          {/* Quick Links */}
          <div>
            <h3 className="text-sm font-semibold uppercase tracking-widest mb-5" style={{ color: '#E8D5B0' }}>
              Quick Links
            </h3>
            <ul className="space-y-3">
              {[
                { to: '/', label: 'Home' },
                { to: '/products', label: 'All Products' },
                { to: '/about', label: 'Our Story' },
                { to: '/about', label: 'Meet the Team' },
              ].map(({ to, label }) => (
                <li key={label}>
                  <Link
                    to={to}
                    className="text-sm transition-colors duration-200 hover:text-primary"
                    style={{ color: '#A8C5BC' }}
                  >
                    {label}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Categories */}
          <div>
            <h3 className="text-sm font-semibold uppercase tracking-widest mb-5" style={{ color: '#E8D5B0' }}>
              Categories
            </h3>
            <ul className="space-y-3">
              {['Pottery', 'Textiles', 'Woodwork', 'Jewelry'].map((cat) => (
                <li key={cat}>
                  <Link
                    to="/products"
                    className="text-sm transition-colors duration-200 hover:text-primary"
                    style={{ color: '#A8C5BC' }}
                  >
                    {cat}
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Newsletter */}
          <div>
            <h3 className="text-sm font-semibold uppercase tracking-widest mb-5" style={{ color: '#E8D5B0' }}>
