            <p className="text-sm mb-4" style={{ color: '#A8C5BC' }}>
              Get new arrivals and artisan stories delivered to your inbox.
            </p>
            {subscribed ? (
              <p className="text-sm font-medium" style={{ color: '#C4622D' }}>
