                  className="flex-1 min-w-0 px-3 py-2 text-sm rounded-lg outline-none focus:ring-2 focus:ring-primary"
                  style={{ backgroundColor: '#2D4A3E', color: '#F5EFE0', border: '1px solid #3D6A5E' }}
                />
                <button
                  type="submit"
                  className="p-2 rounded-lg transition-colors duration-200 hover:opacity-90 shrink-0"
                  style={{ backgroundColor: '#C4622D' }}
