import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'motion/react';
import { ArrowRight, ChevronRight } from 'lucide-react';
import { Helmet } from '@dr.pogodin/react-helmet';

interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  description: string;
  imageUrl: string;
}

const categoryColors: Record<string, string> = {
  pottery: '#C4622D',
  textiles: '#2D4A3E',
  woodwork: '#7C5C3A',
  jewelry: '#8B6B4A',
};

function FeaturedProductCard({
  product,
  large = false,
}: {
  product: Product;
  large?: boolean;
}) {
  return (
    <motion.div
      className={`group relative overflow-hidden rounded-2xl bg-card shadow-sm cursor-pointer ${large ? 'row-span-2' : ''}`}
      whileHover={{ y: -4, boxShadow: '0 16px 40px rgba(0,0,0,0.12)' }}
      transition={{ duration: 0.3, ease: 'easeOut' }}
    >
      <div className={`relative overflow-hidden ${large ? 'h-full min-h-[480px]' : 'aspect-square'}`}>
        <img
          src={product.imageUrl}
          alt={product.name}
          className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
        />
        {/* Hover overlay */}
        <div className="absolute inset-0 bg-black/0 group-hover:bg-black/20 transition-all duration-300 flex items-center justify-center">
          <span className="opacity-0 group-hover:opacity-100 transition-opacity duration-300 bg-white text-foreground text-sm font-semibold px-5 py-2.5 rounded-full shadow-lg">
            View Product
          </span>
        </div>
      </div>
      <div className="p-4">
        <span
          className="inline-block text-xs font-semibold uppercase tracking-wider px-2.5 py-1 rounded-full text-white mb-2"
          style={{ backgroundColor: categoryColors[product.category] || '#C4622D' }}
        >
          {product.category}
        </span>
        <h3 className="font-semibold text-foreground leading-snug mb-1">{product.name}</h3>
        <p className="text-primary font-bold">${product.price}</p>
      </div>
    </motion.div>
  );
}

export default function HomePage() {
  const [products, setProducts] = useState<Product[]>([]);
  const [email, setEmail] = useState('');
  const [subscribed, setSubscribed] = useState(false);

  useEffect(() => {
    fetch('/api/products')
      .then((r) => r.json())
      .then((data) => setProducts(data))
      .catch(console.error);
  }, []);

  const featured = products.slice(0, 4);

  const handleSubscribe = (e: React.FormEvent) => {
    e.preventDefault();
    if (email) {
      setSubscribed(true);
      setEmail('');
    }
  };

  return (
    <>
      <Helmet>
        <title>Artisan Goods Co. — Crafted with Care, Made to Last</title>
        <meta
          name="description"
          content="Discover handmade pottery, textiles, woodwork, and jewelry from skilled artisans. Each piece is unique, crafted with care and made to last."
        />
      </Helmet>

      {/* ── Hero ── */}
      <section className="relative min-h-[90vh] flex items-center overflow-hidden">
        <img
          src="/airo-assets/images/pages/home/hero"
          alt="Artisan workshop with handmade goods"
          className="absolute inset-0 w-full h-full object-cover"
          fetchPriority="high"
        />
        {/* Gradient overlay */}
        <div
          className="absolute inset-0"
          style={{
            background:
              'linear-gradient(105deg, rgba(196,98,45,0.82) 0%, rgba(45,74,62,0.55) 55%, rgba(0,0,0,0.15) 100%)',
          }}
        />
        <div className="relative z-10 max-w-7xl mx-auto px-6 lg:px-8 py-24">
          <motion.div
            initial={{ opacity: 0, y: 32 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.7, ease: 'easeOut' }}
            className="max-w-2xl"
          >
            <span className="inline-block text-xs font-semibold uppercase tracking-widest text-white/80 mb-4 border border-white/30 px-3 py-1 rounded-full">
              Handmade with Heart
            </span>
            <h1
              className="text-5xl md:text-6xl lg:text-7xl font-bold text-white leading-tight mb-6"
              style={{ fontFamily: 'var(--font-heading)' }}
            >
              Crafted with Care,
              <br />
              Made to Last
            </h1>
            <p className="text-lg md:text-xl text-white/85 leading-relaxed mb-10 max-w-xl">
              Discover one-of-a-kind pottery, textiles, woodwork, and jewelry — each piece made by
              hand, with intention, by skilled artisans.
            </p>
            <div className="flex flex-wrap gap-4">
              <motion.div whileHover={{ scale: 1.04 }} whileTap={{ scale: 0.97 }}>
                <Link
                  to="/products"
                  className="inline-flex items-center gap-2 px-7 py-3.5 rounded-full font-semibold text-white shadow-lg transition-opacity hover:opacity-90"
                  style={{ backgroundColor: '#C4622D' }}
                >
                  Shop Now <ArrowRight size={18} />
                </Link>
              </motion.div>
              <motion.div whileHover={{ scale: 1.04 }} whileTap={{ scale: 0.97 }}>
                <Link
                  to="/about"
                  className="inline-flex items-center gap-2 px-7 py-3.5 rounded-full font-semibold text-white border-2 border-white/60 hover:border-white transition-colors"
                >
                  Our Story <ChevronRight size={18} />
                </Link>
              </motion.div>
            </div>
          </motion.div>
        </div>
      </section>

      {/* ── Featured Products ── */}
      <section className="py-20 lg:py-28" style={{ backgroundColor: '#F5EFE0' }}>
        <div className="max-w-7xl mx-auto px-6 lg:px-8">
          <motion.div
            initial={{ opacity: 0, y: 24 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ duration: 0.5, ease: 'easeOut' }}
            className="flex flex-col sm:flex-row sm:items-end justify-between gap-4 mb-12"
          >
            <div>
              <span className="text-xs font-semibold uppercase tracking-widest text-primary mb-2 block">
                Handpicked for You
              </span>
              <h2
                className="text-4xl md:text-5xl font-bold text-foreground"
                style={{ fontFamily: 'var(--font-heading)' }}
              >
                Featured Pieces
              </h2>
            </div>
            <Link
              to="/products"
              className="inline-flex items-center gap-1.5 text-sm font-semibold text-primary hover:underline shrink-0"
            >
              Browse All Products <ArrowRight size={16} />
            </Link>
          </motion.div>

          {featured.length > 0 ? (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 auto-rows-auto">
              {/* Large featured card */}
              {featured[0] && (
                <motion.div
                  className="lg:row-span-2"
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: 0.05, ease: 'easeOut' }}
                >
                  <Link to="/products">
                    <FeaturedProductCard product={featured[0]} large />
                  </Link>
                </motion.div>
              )}
              {/* Remaining 3 cards */}
              {featured.slice(1).map((product, i) => (
                <motion.div
                  key={product.id}
                  initial={{ opacity: 0, y: 24 }}
                  whileInView={{ opacity: 1, y: 0 }}
                  viewport={{ once: true }}
                  transition={{ duration: 0.5, delay: 0.1 + i * 0.08, ease: 'easeOut' }}
                >
                  <Link to="/products">
                    <FeaturedProductCard product={product} />
                  </Link>
                </motion.div>
              ))}
            </div>
          ) : (
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
              {Array.from({ length: 4 }).map((_, i) => (
                <div key={i} className={`rounded-2xl bg-muted animate-pulse ${i === 0 ? 'lg:row-span-2 min-h-[480px]' : 'aspect-square'}`} />
              ))}
            </div>
          )}
        </div>
      </section>

      {/* ── Craft Story Banner ── */}
      <motion.section
        initial={{ opacity: 0 }}
        whileInView={{ opacity: 1 }}
