/**
 * Products Service
 *
 * Single source of truth for product data types and fetching.
 * All product data lives in the API handler:
 *   src/server/api/products/GET.ts
 *
 * To add, edit, or remove products, update that file.
 * To change how products are fetched or shaped, update this file.
 */

export type ProductCategory = 'pottery' | 'textiles' | 'woodwork' | 'jewelry';

export interface Product {
  id: string;
  name: string;
  category: ProductCategory;
  price: number;
  description: string;
  imageUrl: string;
}

/**
 * Fetch all products from the API.
 * Suitable for use in React Router loaders (SSR) and client-side useEffect.
 */
export async function fetchProducts(): Promise<Product[]> {
  const res = await fetch('/api/products');
  if (!res.ok) {
    throw new Error(`Failed to fetch products: ${res.status} ${res.statusText}`);
  }
  return res.json() as Promise<Product[]>;
}

